// PLAN RUN — decides what to make: category (learned weights), recurring star or new character,
// and what must not be repeated. Returns NO items (= quiet stop) if another video is still in progress.
const cfg = $('Config').first().json.cfg;
const rows = (node) => {
  try { return $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length); } catch (e) { return []; }
};
const history = rows('Read History').filter((r) => r.video_id);
const weightRows = rows('Read Topic Weights').filter((r) => r.category);
const stars = rows('Read Characters').filter((r) => r.char_id && String(r.recurring).toLowerCase() === 'yes');
const now = new Date();

// 1) Guard against overlapping runs (manual run + schedule, or a slow render)
const busy = history.find((r) => ['generating', 'rendering', 'uploading'].includes(r.status) &&
  now - new Date(r.created_at) < 6 * 3600 * 1000);
if (busy) return [];

// 2) Category: weighted random using weights written by the Analytics workflow
const weights = Object.fromEntries(cfg.categories.map((c) => [c, 1]));
for (const r of weightRows) {
  const w = Number(r.weight);
  if (r.category in weights && w > 0) weights[r.category] = Math.min(3, Math.max(0.4, w));
}
for (const c of history.slice(-3).map((r) => r.category)) if (c in weights) weights[c] *= 0.35; // variety
const learned = weightRows.length > 0;
const weightsNote = learned
  ? Object.entries(weights).sort((a, b) => b[1] - a[1]).map(([c, w]) => `${c} ${w.toFixed(2)}`).join(', ')
  : '';
let roll = Math.random() * Object.values(weights).reduce((a, b) => a + b, 0);
let category = cfg.categories[0];
for (const [c, w] of Object.entries(weights)) { roll -= w; if (roll <= 0) { category = c; break; } }

// 3) Recurring star (builds a recognisable cast) vs new character; block over-used species
const speciesCount = {};
for (const r of history.slice(-10)) {
  const s = String(r.main_species || '').toLowerCase().trim();
  if (s) speciesCount[s] = (speciesCount[s] || 0) + 1;
}
const bannedSpecies = Object.entries(speciesCount).filter(([, n]) => n >= 3).map(([s]) => s);
const recentIds = history.slice(-2).flatMap((r) => String(r.char_ids || '').split(',').map((s) => s.trim()));
const eligible = stars.filter((s) => !recentIds.includes(s.char_id));
let star = null;
if (eligible.length && Math.random() < Number(cfg.recurring_star_probability ?? 0.5)) {
  eligible.sort((a, b) => Number(a.appearances || 0) - Number(b.appearances || 0));
  const s = eligible[0];
  star = { char_id: s.char_id, name: s.name, species: s.species, short_tag: s.short_tag, visual_prompt: s.visual_prompt, personality: s.personality || '' };
}

// 4) Soft avoid-lists for the prompt (hard duplicate checks run after generation)
const done = history.filter((r) => r.status !== 'failed');
const month = now.toLocaleString('en-US', { month: 'long', timeZone: 'Asia/Kolkata' });
const season = ['winter', 'winter', 'spring', 'spring', 'spring', 'summer', 'summer', 'summer', 'autumn', 'autumn', 'autumn', 'winter'][now.getUTCMonth()];
const stamp = now.toISOString().slice(0, 10).replace(/-/g, '');
const rand = Array.from({ length: 4 }, () => 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[Math.floor(Math.random() * 32)]).join('');

const pkg = {
  video_id: `NR-${stamp}-${rand}`,
  exec_id: String($execution.id),
  started_at: now.toISOString(),
  cfg,
  plan: {
    category, month, season, star,
    banned_species: bannedSpecies,
    avoid_titles: done.slice(-60).map((r) => r.title).filter(Boolean),
    avoid_concepts: done.slice(-40).map((r) => r.concept_keywords).filter(Boolean),
    target_duration_s: cfg.target_duration_s,
    weights_note: weightsNote,
  },
  hash: {},
  checks: {},
  llm_log: [],
};
return [{ json: { pkg, feedback: '' } }];

// CHECK IDEA — duplicate + originality gate for the concept. Routes: 0 ok, 1 retry, 2 fail.
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const idea = pkg.idea;
const attempt = $runIndex; // how many ideas were already checked in this execution
const MAX_RETRIES = 2;

const STOP = new Set(['the', 'a', 'an', 'and', 'of', 'for', 'to', 'in', 'on', 'with', 'song', 'rhyme', 'nursery', 'kids', 'little', 'my', 'our', 'is', 'are', 'at', 'by']);
const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const normTitle = (s) => norm(s).split(' ').filter((w) => w && !STOP.has(w)).join(' ');
const grams = (s, n = 3) => { const t = ` ${s} `; const out = new Set(); for (let i = 0; i + n <= t.length; i++) out.add(t.slice(i, i + n)); return out; };
const jaccard = (a, b) => { if (!a.size || !b.size) return 0; let n = 0; for (const x of a) if (b.has(x)) n++; return n / (a.size + b.size - n); };
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const kw = (arr) => new Set((arr || []).map((x) => norm(x)).filter(Boolean));
const FAMOUS = ['twinkle twinkle', 'wheels on the bus', 'baby shark', 'old macdonald', 'mary had a little lamb', 'humpty dumpty', 'itsy bitsy spider', 'incy wincy', 'row row row your boat', 'jack and jill', 'hickory dickory', 'london bridge', 'baa baa black sheep', 'five little monkeys', 'head shoulders knees', 'happy and you know it', 'johny johny', 'rain rain go away', 'hey diddle diddle', 'little miss muffet', 'pat a cake', 'ring around the rosie', 'this old man', 'farmer in the dell', 'old king cole', 'little bo peep', 'three blind mice', 'hot cross buns', 'ten in the bed', 'five little ducks', 'ants go marching', 'little teapot', 'muffin man', 'pop goes the weasel', 'bluey', 'peppa', 'cocomelon', 'paw patrol', 'pinkfong', 'super simple songs', 'little baby bum', 'blippi', 'disney', 'pixar', 'frozen', 'mickey', 'minnie', 'elsa', 'pokemon', 'pikachu', 'sesame street', 'elmo', 'barney', 'teletubbies', 'spongebob', 'winnie the pooh', 'paddington', 'thomas the tank', 'hello kitty', 'minions', 'gabby'];

let hist = [];
try { hist = $('Read History').all().map((i) => i.json).filter((r) => r.video_id && r.status !== 'failed'); } catch (e) { hist = []; }
const problems = [];
const tNorm = normTitle(idea.title);
const tGrams = grams(tNorm);
const kwSet = kw(idea.concept_keywords);
const species = norm(idea.main_character?.species);
const conceptHash = fnv1a([norm(idea.category), ...[...kwSet].sort(), species].join('|'));

for (const r of hist) {
  const rt = String(r.title_norm || normTitle(r.title));
  if (rt && (rt === tNorm || jaccard(grams(rt), tGrams) >= 0.6)) problems.push(`the title is too similar to our existing video "${r.title}"`);
  if (r.concept_hash && r.concept_hash === conceptHash) problems.push(`the concept is identical to "${r.title}"`);
  const rk = kw(String(r.concept_keywords || '').split(','));
  if (rk.size >= 3 && norm(r.category) === norm(idea.category) && jaccard(rk, kwSet) >= 0.6) problems.push(`the concept keywords overlap heavily with "${r.title}"`);
}
const text = ` ${norm(`${idea.title} ${idea.premise} ${idea.main_character?.name} ${idea.search_phrase}`)} `;
const phraseWords = norm(idea.search_phrase).split(' ').filter(Boolean);
if (phraseWords.length < 2 || phraseWords.length > 6) problems.push('search_phrase must be a real 2-5 word phrase a parent would type');
for (const f of FAMOUS) if (text.includes(` ${f} `)) problems.push(`it refers to an existing song or brand ("${f}")`);
if (!idea.main_character?.reuse_star && (pkg.plan.banned_species ?? []).includes(species)) problems.push(`the species "${species}" was used too often recently`);
if (pkg.plan.star && idea.main_character?.reuse_star && norm(idea.main_character.name) !== norm(pkg.plan.star.name)) problems.push(`reuse_star is true but the name is not "${pkg.plan.star.name}"`);
if (!pkg.cfg.categories.includes(idea.category)) idea.category = pkg.plan.category; // auto-fix

const list = [...new Set(problems)].slice(0, 6);
const route = list.length === 0 ? 'ok' : (attempt < MAX_RETRIES ? 'retry' : 'fail');
pkg.hash = { ...pkg.hash, title_norm: tNorm, concept_hash: conceptHash };
pkg.checks.idea = { attempt: attempt + 1, problems: list };
return [{
  json: {
    pkg, route, route_index: { ok: 0, retry: 1, fail: 2 }[route],
    fail_reason: route === 'fail' ? `${pkg.video_id} | idea rejected after ${attempt + 1} attempts: ${list.join('; ')}` : '',
    feedback: list.length ? `The previous idea "${idea.title}" was rejected because ${list.join('; ')}. Propose a clearly different idea.` : '',
  },
}];

// CHECK SONG — structure, safety words, copying from famous rhymes, near-duplicates of our own songs,
// character bible clean-up. Auto-fixes small things; routes 0 ok, 1 retry, 2 fail.
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const song = pkg.song;
const attempt = $runIndex; // counts every song check in this execution (incl. QC revisions)
const MAX_RUNS = 4;

const norm = (s) => String(s || '').toLowerCase().normalize('NFKD').replace(/[’']/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
const ngrams = (s, n) => { const w = norm(s).split(' ').filter(Boolean); const out = new Set(); for (let i = 0; i + n <= w.length; i++) out.add(w.slice(i, i + n).join(' ')); return out; };
const jaccard = (a, b) => { if (!a.size || !b.size) return 0; let n = 0; for (const x of a) if (b.has(x)) n++; return n / (a.size + b.size - n); };
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); };
const slug = (s) => norm(s).replace(/ /g, '_').slice(0, 40);
const problems = [];
const fixes = [];

// --- structure -------------------------------------------------------------
const secs = (song.sections || []).filter((s) => Array.isArray(s.lines) && s.lines.some((l) => String(l).trim()));
const seenIds = {};
secs.forEach((s, i) => {
  s.lines = s.lines.map((l) => String(l).replace(/\s+/g, ' ').trim()).filter(Boolean);
  let id = slug(s.section_id) || `section_${i + 1}`;
  if (seenIds[id]) { seenIds[id] += 1; id = `${id}_${seenIds[id]}`; fixes.push('renamed duplicate section ids'); } else seenIds[id] = 1;
  s.section_id = id;
});
const choruses = secs.filter((s) => s.type === 'chorus');
if (choruses.length < 2) problems.push('the chorus must appear at least twice, identical each time');
else {
  for (const c of choruses.slice(1)) {
    if (JSON.stringify(c.lines) !== JSON.stringify(choruses[0].lines)) { c.lines = [...choruses[0].lines]; fixes.push('made every chorus identical'); }
  }
}
const lines = secs.flatMap((s) => s.lines);
if (lines.length < 16 || lines.length > 40) problems.push(`the song has ${lines.length} lines; write 18-36`);
const tooLong = lines.filter((l) => l.split(' ').length > 11);
if (tooLong.length) problems.push(`these lines are too long to sing (max 9-10 words): ${tooLong.slice(0, 3).map((l) => `"${l}"`).join(', ')}`);

// --- toddler-safety vocabulary ------------------------------------------------
const BANNED = ['kill', 'killed', 'kills', 'die', 'dies', 'died', 'dead', 'death', 'blood', 'bloody', 'gun', 'guns', 'knife', 'knives', 'sword', 'hate', 'stupid', 'idiot', 'dumb', 'shut up', 'ugly', 'fat', 'beer', 'wine', 'cigarette', 'drunk', 'sexy', 'scary', 'monster', 'ghost', 'devil', 'hell', 'poop', 'fart', 'vomit', 'candy reward'];
const hay = ` ${norm(lines.join(' '))} `;
const hits = BANNED.filter((w) => hay.includes(` ${w} `));
if (hits.length) problems.push(`remove words unsuitable for toddlers: ${hits.join(', ')}`);

// --- copying from well-known rhymes (any 4 consecutive words) --------------------
const FAMOUS_LINES = ['twinkle twinkle little star how i wonder what you are', 'up above the world so high like a diamond in the sky', 'the wheels on the bus go round and round', 'old macdonald had a farm e i e i o', 'row row row your boat gently down the stream', 'merrily merrily merrily merrily life is but a dream', 'mary had a little lamb its fleece was white as snow', 'humpty dumpty sat on a wall humpty dumpty had a great fall', 'the itsy bitsy spider climbed up the water spout', 'jack and jill went up the hill to fetch a pail of water', 'hickory dickory dock the mouse ran up the clock', 'london bridge is falling down my fair lady', 'baa baa black sheep have you any wool', 'five little monkeys jumping on the bed', 'head shoulders knees and toes', 'if youre happy and you know it clap your hands', 'johny johny yes papa eating sugar no papa', 'rain rain go away come again another day', 'hey diddle diddle the cat and the fiddle the cow jumped over the moon', 'baby shark doo doo doo doo doo doo', 'im a little teapot short and stout', 'the ants go marching one by one hurrah hurrah', 'this old man he played one he played knick knack on my thumb', 'pat a cake pat a cake bakers man', 'ring around the rosie a pocket full of posies', 'three blind mice see how they run', 'hot cross buns one a penny two a penny', 'little bo peep has lost her sheep', 'the farmer in the dell', 'pop goes the weasel', 'do your ears hang low', 'five little ducks went out one day over the hill and far away', 'there were ten in the bed and the little one said roll over', 'do you know the muffin man who lives on drury lane', 'you are my sunshine my only sunshine', 'happy birthday to you', 'the more we get together together together', 'this is the way we wash our hands', 'where is thumbkin where is thumbkin', 'are you sleeping are you sleeping brother john morning bells are ringing', 'one two buckle my shoe three four shut the door', 'the grand old duke of york he had ten thousand men', 'sing a song of sixpence a pocket full of rye', 'polly put the kettle on', 'it is raining it is pouring the old man is snoring', 'teddy bear teddy bear turn around', 'the bear went over the mountain to see what he could see', 'down by the bay where the watermelons grow', 'skinnamarink a dink a dink skinnamarink a doo'];
const famous4 = new Set();
FAMOUS_LINES.forEach((l) => ngrams(l, 4).forEach((g) => famous4.add(g)));
const copied = lines.filter((l) => [...ngrams(l, 4)].some((g) => famous4.has(g)));
if (copied.length) problems.push(`these lines are too close to existing nursery rhymes - rewrite them: ${copied.slice(0, 3).map((l) => `"${l}"`).join(', ')}`);

// --- near-identical to our own earlier songs -------------------------------------
let hist = [];
try { hist = $('Read History').all().map((i) => i.json).filter((r) => r.video_id && r.lyrics && r.status !== 'failed'); } catch (e) { hist = []; }
const mine = ngrams(lines.join(' '), 3);
let worst = { sim: 0, title: '' };
for (const r of hist) {
  const sim = jaccard(mine, ngrams(String(r.lyrics).replace(/\[[^\]]*\]/g, ' '), 3));
  if (sim > worst.sim) worst = { sim, title: r.title };
}
if (worst.sim >= 0.25) problems.push(`the lyrics are ${Math.round(worst.sim * 100)}% similar to our earlier song "${worst.title}" - write new lines`);

// --- character bible -------------------------------------------------------------
const FRANCHISE = ['mickey', 'minnie', 'elsa', 'olaf', 'simba', 'nemo', 'dory', 'pooh', 'tigger', 'peppa', 'bluey', 'bingo heeler', 'chase', 'marshall', 'pikachu', 'elmo', 'barney', 'spongebob', 'thomas', 'cocomelon', 'blippi', 'hello kitty', 'paddington', 'shrek', 'minion', 'stitch', 'moana', 'baby shark'];
let chars = (song.characters || []).slice(0, 3);
if (!chars.length) problems.push('define at least one character in the character bible');
const usedIds = new Set();
chars.forEach((c, i) => {
  let id = slug(c.char_id || c.name) || `char_${i + 1}`;
  while (usedIds.has(id)) id = `${id}_${i + 1}`;
  usedIds.add(id);
  c.char_id = id;
  if (FRANCHISE.includes(norm(c.name))) problems.push(`the character name "${c.name}" belongs to an existing franchise`);
  const words = String(c.visual_prompt || '').split(/\s+/);
  if (words.length > 40) { c.visual_prompt = words.slice(0, 40).join(' '); fixes.push('shortened a visual_prompt'); }
  if (!c.short_tag) c.short_tag = `${c.species}`;
  if (!['main', 'friend'].includes(c.role)) c.role = i === 0 ? 'main' : 'friend';
});
if (chars.length && !chars.some((c) => c.role === 'main')) chars[0].role = 'main';
const star = pkg.plan.star;
if (star && pkg.idea?.main_character?.reuse_star) { // recurring star: stored bible always wins
  const idx = chars.findIndex((c) => norm(c.name) === norm(star.name));
  const fixed = { ...(chars[idx] || {}), char_id: star.char_id, name: star.name, species: star.species, visual_prompt: star.visual_prompt, short_tag: star.short_tag, personality: star.personality || chars[idx]?.personality || '', role: 'main' };
  if (idx >= 0) chars[idx] = fixed; else chars = [fixed, ...chars].slice(0, 3);
  chars.forEach((c) => { if (c.char_id !== star.char_id) c.role = 'friend'; });
  fixes.push('applied the recurring star bible');
}
for (const member of pkg.cfg.cast || []) { // recurring friends also keep their stored bible
  const idx = chars.findIndex((c) => norm(c.name) === norm(member.name) || c.char_id === member.char_id);
  if (idx >= 0 && chars[idx].char_id !== star?.char_id) {
    chars[idx] = { ...chars[idx], char_id: member.char_id, name: member.name, species: member.species, visual_prompt: member.visual_prompt, short_tag: member.short_tag, personality: chars[idx].personality || member.personality };
    fixes.push(`applied the stored bible for ${member.name}`);
  }
}
song.sections = secs;
song.characters = chars;

// --- music + voice sanity ------------------------------------------------------
song.music = song.music || {};
song.music.bpm = Math.min(126, Math.max(90, parseInt(song.music.bpm, 10) || 108));
if (!['3', '4'].includes(String(song.music.time_signature))) song.music.time_signature = '4';
song.music.caption = String(song.music.caption || 'cheerful children\'s song, bright friendly female vocal, ukulele, glockenspiel, hand claps').slice(0, 300);
song.voice = song.voice || {};

pkg.lyrics_text = secs.map((s) => `[${s.section_id}]\n${s.lines.join('\n')}`).join('\n\n');
pkg.hash.lyrics_hash = fnv1a(norm(lines.join(' ')));
const list = [...new Set(problems)].slice(0, 6);
const route = list.length === 0 ? 'ok' : (attempt < MAX_RUNS - 1 ? 'retry' : 'fail');
pkg.checks.song = { attempt: attempt + 1, problems: list, fixes: [...new Set(fixes)], similarity_to_own: Math.round(worst.sim * 100) / 100 };
return [{
  json: {
    pkg, route, route_index: { ok: 0, retry: 1, fail: 2 }[route],
    fail_reason: route === 'fail' ? `${pkg.video_id} | song rejected after ${attempt + 1} checks: ${list.join('; ')}` : '',
    feedback: list.length ? `Your previous song was rejected. Fix ALL of these and keep everything else that worked:\n- ${list.join('\n- ')}` : '',
  },
}];

// CHECK STORYBOARD — maps scenes to global lyric lines, enforces coverage + enums, and BUILDS every
// image prompt from the shared style bible + character bible (deterministic consistency).
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const sb = pkg.storyboard;
const song = pkg.song;
const cfg = pkg.cfg;
const attempt = $runIndex;
const MAX_RUNS = 4;
const CAMERA = ['zoom_in', 'zoom_out', 'pan_left', 'pan_right', 'pan_up', 'pan_down', 'static'];
const TRANS = ['fade', 'dissolve', 'slideleft', 'slideright', 'wipeleft', 'wiperight', 'circleopen', 'smoothleft', 'smoothright', 'radial'];
const SFX = ['splash', 'pop', 'boing', 'chime', 'whoosh', 'giggle', 'clap', 'bell', 'footsteps', 'bird_chirp', 'rain_light', 'wind_soft', 'car_horn_toy', 'train_toot', 'animal_moo', 'animal_quack', 'animal_roar_cute', 'drum_roll', 'ding', 'snore'];
const problems = [];
const fixes = [];
const clean = (s, max = 30) => String(s || '').replace(/[\r\n"]+/g, ' ').replace(/\s+/g, ' ').trim().split(' ').slice(0, max).join(' ');

// global line index
const flat = [];
const secIndex = {};
for (const s of song.sections) {
  secIndex[s.section_id] = { start: flat.length, len: s.lines.length };
  s.lines.forEach((t, li) => flat.push({ gi: flat.length, section_id: s.section_id, li, text: t }));
}
const bible = Object.fromEntries(song.characters.map((c) => [c.char_id, c]));
const mainId = (song.characters.find((c) => c.role === 'main') || song.characters[0]).char_id;

let scenes = [];
for (const sc of sb.scenes || []) {
  const key = Object.keys(secIndex).find((k) => k === sc.section_id) ||
    Object.keys(secIndex).find((k) => k.replace(/_/g, '') === String(sc.section_id).toLowerCase().replace(/[^a-z0-9]/g, ''));
  if (!key) { fixes.push('dropped scenes with unknown section ids'); continue; }
  const sec = secIndex[key];
  const gl = [...new Set((sc.line_indices || []).map(Number).filter((n) => Number.isInteger(n) && n >= 0 && n < sec.len))]
    .sort((a, b) => a - b).map((n) => sec.start + n);
  if (!gl.length) { fixes.push('dropped scenes without valid lines'); continue; }
  const ids = (sc.char_ids || []).filter((id) => bible[id]).slice(0, 2);
  if (ids.length !== (sc.char_ids || []).length) fixes.push('removed unknown character ids');
  scenes.push({
    lines: gl, char_ids: ids, setting: clean(sc.setting, 18), action: clean(sc.action, 22), expression: clean(sc.expression, 8),
    framing: ['wide shot', 'medium shot', 'close-up'].includes(sc.framing) ? sc.framing : 'medium shot',
    camera: CAMERA.includes(sc.camera) ? sc.camera : 'zoom_in',
    transition: TRANS.includes(sc.transition) ? sc.transition : 'fade',
    sfx: (sc.sfx || []).filter((f) => SFX.includes(f.name)).slice(0, 1).map((f) => ({ name: f.name, at: f.at === 'middle' ? 'middle' : 'start' })),
  });
}
scenes.sort((a, b) => a.lines[0] - b.lines[0]);

// coverage: every lyric line must be inside some scene
const covered = new Set(scenes.flatMap((s) => s.lines));
const missing = flat.filter((l) => !covered.has(l.gi)).map((l) => l.gi);
if (missing.length > Math.max(3, Math.floor(flat.length * 0.2))) {
  problems.push(`scenes leave ${missing.length} lyric lines uncovered (e.g. section ${flat[missing[0]].section_id} line ${flat[missing[0]].li})`);
} else if (missing.length && scenes.length) {
  for (const gi of missing) {
    const host = [...scenes].reverse().find((s) => s.lines[0] <= gi) || scenes[0];
    host.lines = [...host.lines, gi].sort((a, b) => a - b);
  }
  fixes.push(`attached ${missing.length} uncovered lines to neighbouring scenes`);
}
if (scenes.length < 10) problems.push(`only ${scenes.length} usable scenes; make 14-32`);
if (scenes.length > 40) problems.push(`${scenes.length} scenes is too many; make 14-32`);
const withMain = scenes.filter((s) => s.char_ids.includes(mainId)).length;
if (scenes.length && withMain / scenes.length < 0.4) problems.push('the main character should appear in most scenes');

// prompts: style bible + character short tags + scene description
const style = cfg.style_bible.positive;
const tags = (ids) => ids.map((id) => bible[id].short_tag).join(' and ');
const build = (...parts) => parts.filter((p) => p && String(p).trim()).join(', ').replace(/\s+/g, ' ');
scenes = scenes.map((s, i) => ({
  ...s, scene_id: i + 1,
  prompt: build(style, s.framing, tags(s.char_ids), s.action, s.expression && `${s.expression} expression`, s.setting),
}));
const card = (c, fallbackAction, extra) => {
  const ids = ((c && c.char_ids) || []).filter((id) => bible[id]).slice(0, 2);
  const useIds = ids.length ? ids : [mainId];
  return { char_ids: useIds, prompt: build(style, 'wide shot', tags(useIds), clean(c?.action, 20) || fallbackAction, clean(c?.setting, 16), extra) };
};
const th = sb.thumbnail || {};
const side = th.text_side === 'right' ? 'right' : 'left';
const thumbText = clean(String(th.text || song.title).replace(/[^\p{L}\p{N}!?' ]/gu, ''), 4);
pkg.render_scenes = scenes;
pkg.cards = {
  title_card: card(sb.title_card, 'waving hello happily at the viewer', 'empty space at the top of the picture'),
  outro_card: card(sb.outro_card, 'waving goodbye happily', 'empty space at the top of the picture'),
  thumbnail: {
    char_ids: [mainId], text: thumbText, text_side: side,
    prompt: build(style, 'close-up', tags([mainId]), clean(th.action, 16), `${clean(th.expression, 6) || 'big happy'} expression`,
      clean(th.background, 10) || 'plain bright sky blue background', `character placed on the ${side === 'left' ? 'right' : 'left'} side`, 'simple composition'),
  },
};
const list = [...new Set(problems)].slice(0, 6);
const route = list.length === 0 ? 'ok' : (attempt < MAX_RUNS - 1 ? 'retry' : 'fail');
pkg.checks.storyboard = { attempt: attempt + 1, problems: list, fixes: [...new Set(fixes)], scenes: scenes.length };
return [{
  json: {
    pkg, route, route_index: { ok: 0, retry: 1, fail: 2 }[route],
    fail_reason: route === 'fail' ? `${pkg.video_id} | storyboard rejected after ${attempt + 1} checks: ${list.join('; ')}` : '',
    feedback: list.length ? `Your previous storyboard was rejected. Fix ALL of these:\n- ${list.join('\n- ')}` : '',
  },
}];

// CHECK METADATA — enforces YouTube limits and honesty rules. Always auto-fixes; never fails.
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const md = pkg.metadata;
const strip = (s) => String(s || '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
const BRANDS = ['cocomelon', 'pinkfong', 'baby shark', 'bluey', 'peppa', 'disney', 'pixar', 'paw patrol', 'super simple', 'little baby bum', 'blippi', 'sesame', 'mickey', 'frozen', 'pokemon', 'chuchu', 'bebefinn', 'masha'];

let title = strip(md.title);
// de-shout: words of 4+ letters in ALL CAPS read as clickbait
title = title.split(' ').map((w) => (w.length > 3 && /[A-Z]/.test(w) && w === w.toUpperCase() ? w[0] + w.slice(1).toLowerCase() : w)).join(' ');
title = title.replace(/[!?]{2,}/g, '!');
if (BRANDS.some((b) => title.toLowerCase().includes(b))) title = pkg.song.title; // never borrow other brands
const phrase = String(pkg.idea?.search_phrase || '').trim();
const words = (s) => String(s).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((w) => w.length > 2);
const pw = words(phrase);
const covered = pw.filter((w) => words(title).includes(w)).length;
if (pw.length && covered / pw.length < 0.6) { // add the searchable phrase if the AI left it out
  const titleCase = phrase.replace(/\b\w/g, (c) => c.toUpperCase());
  const base = title.split(' | ')[0];
  if ((base + ' | ' + titleCase).length <= 90) title = `${base} | ${titleCase}`;
}
if (title.length > 100) title = title.slice(0, 97).replace(/\s+\S*$/, '') + '...';

let description = String(md.description || '').replace(/[<>]/g, '').replace(/https?:\/\/\S+/g, '').replace(/#\w+/g, '').trim();
if (description.length > 2500) description = description.slice(0, 2500).replace(/\s+\S*$/, '') + '...';

const tags = [];
let budget = 0; // YouTube: 500 characters for all tags; multi-word tags count their quotes
for (const raw of md.tags || []) {
  const t = strip(raw).toLowerCase().replace(/[,#"]/g, '');
  if (!t || t.length > 30 || tags.includes(t) || BRANDS.some((b) => t.includes(b))) continue;
  const cost = t.length + (t.includes(' ') ? 2 : 0) + 1;
  if (budget + cost > 450) break;
  tags.push(t);
  budget += cost;
}
const hashtags = (md.hashtags || []).map((h) => String(h).replace(/[^A-Za-z0-9]/g, '')).filter((h) => h && !BRANDS.some((b) => h.toLowerCase().includes(b.replace(/ /g, '')))).slice(0, 3);
pkg.metadata_final = { title, description, tags, hashtags };
return [{ json: { pkg, feedback: '' } }];

// QC GATE — turns the AI reviewer's scores into a decision.
// Routes: 0 pass, 1 revise song, 2 revise storyboard, 3 revise metadata, 4 fail. Max 3 review rounds.
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const qc = pkg.qc;
const round = $runIndex; // 0-based review round in this execution
const MAX_ROUNDS = 3;

const scores = qc.scores || {};
const values = Object.values(scores).map(Number).filter((n) => !Number.isNaN(n));
const core = Object.entries(scores).filter(([k]) => k !== 'algorithm_fit').map(([, v]) => Number(v)).filter((n) => !Number.isNaN(n));
const min = core.length ? Math.min(...core) : 0;
const algoOk = scores.algorithm_fit === undefined || Number(scores.algorithm_fit) >= 6;
const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
const blockers = (qc.issues || []).filter((i) => i.severity === 'blocker');
const passed = qc.verdict === 'pass' && min >= 7 && algoOk && Number(scores.child_safety) >= 9 && blockers.length === 0 && !qc.resembles_existing_work;

let route;
if (passed) route = 'pass';
else if (qc.verdict === 'reject' || round >= MAX_ROUNDS - 1) route = 'fail';
else {
  const rank = { blocker: 3, major: 2, minor: 1 };
  const worst = [...(qc.issues || [])].sort((a, b) => (rank[b.severity] || 0) - (rank[a.severity] || 0))[0];
  route = worst?.component || { revise_song: 'song', revise_storyboard: 'storyboard', revise_metadata: 'metadata' }[qc.verdict] || 'song';
  if (qc.resembles_existing_work) route = 'song';
}
const relevant = (qc.issues || []).filter((i) => route === 'song' || i.component === route);
const feedback = relevant.length
  ? `A reviewer found these problems. Fix ALL of them and keep everything else that works:\n${relevant.map((i) => `- [${i.severity}] ${i.problem} -> fix: ${i.fix}`).join('\n')}`
  : '';
pkg.quality_score = Math.round(avg * 10) / 10;
pkg.checks.qc = { round: round + 1, min_score: min, algorithm_fit: scores.algorithm_fit, verdict: qc.verdict, blockers: blockers.length, summary: qc.summary };
const failText = blockers.concat(qc.issues || []).slice(0, 3).map((i) => i.problem).join('; ');
return [{
  json: {
    pkg, route, feedback,
    route_index: { pass: 0, song: 1, storyboard: 2, metadata: 3, fail: 4 }[route],
    fail_reason: route === 'fail' ? `${pkg.video_id} | content QC failed after ${round + 1} review(s): ${failText || qc.summary}` : '',
  },
}];

// BUILD RENDER JOB — converts the approved package into the helper's job.json (VIDEO schema).
const pkg = JSON.parse(JSON.stringify($input.first().json.pkg));
const cfg = pkg.cfg;
const song = pkg.song;
const fnv1a = (s) => { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h; };

pkg.retry_count = Math.max(0, (pkg.llm_log || []).length - 5); // 5 = one call per stage when nothing fails
const job = {
  video_id: pkg.video_id,
  channel_name: cfg.channel_name,
  title: song.title || pkg.idea.title,
  style_bible: cfg.style_bible,
  characters: song.characters.map((c) => ({
    char_id: c.char_id, name: c.name, species: c.species, short_tag: c.short_tag,
    visual_prompt: c.visual_prompt, seed: fnv1a(c.char_id) % 2147483647,
  })),
  song: {
    sections: song.sections.map((s) => ({ section_id: s.section_id, type: s.type, lines: s.lines })),
    music: {
      caption: song.music.caption, bpm: song.music.bpm, key: song.music.key || 'C Major',
      time_signature: String(song.music.time_signature || '4'), target_duration_s: cfg.target_duration_s,
    },
  },
  voice: { hook_text: song.voice.hook_text, outro_text: song.voice.outro_text, voice: cfg.voice },
  scenes: pkg.render_scenes.map((s) => ({
    scene_id: s.scene_id, lines: s.lines, char_ids: s.char_ids, camera: s.camera,
    transition: s.transition, sfx: s.sfx, prompt: s.prompt,
  })),
  title_card: pkg.cards.title_card,
  outro_card: pkg.cards.outro_card,
  thumbnail: pkg.cards.thumbnail,
  render: { width: 1920, height: 1080, fps: 30, transition_s: 0.5, title_card_s: cfg.title_card_s ?? 3.0, outro_s: 5.0, min_duration_s: cfg.min_duration_s, max_duration_s: cfg.max_duration_s },
  qc: { min_intelligibility: cfg.min_intelligibility, max_song_attempts: 3, max_image_attempts: 2 },
};
return [{ json: { pkg, job } }];

// CHARACTER ROWS — one item per character for the Characters sheet (recurring cast memory).
const { pkg } = $input.first().json;
const existing = {};
try { for (const i of $('Read Characters').all()) if (i.json.char_id) existing[i.json.char_id] = i.json; } catch (e) { /* empty sheet */ }
return pkg.song.characters.map((c) => {
  const old = existing[c.char_id] || {};
  return {
    json: {
      char_id: c.char_id, name: c.name, species: c.species, short_tag: c.short_tag,
      visual_prompt: c.visual_prompt, personality: c.personality || '',
      recurring: old.recurring || (c.role === 'main' ? 'yes' : 'no'),
      first_video: old.first_video || pkg.video_id, last_video: pkg.video_id,
      appearances: Number(old.appearances || 0) + 1,
    },
  };
});

// MEDIA QC GATE — stops the run if the helper's file checks failed, then prepares upload metadata
// (description + chapters + lyrics + disclosure) and the publish slot. Routes: 0 outbox, 1 private, 2 scheduled.
const st = $input.first().json; // helper job status
const pkg = JSON.parse(JSON.stringify($('Build Render Job').first().json.pkg));
const cfg = pkg.cfg;
if (!st.media_qc || !st.media_qc.pass) {
  const bad = Object.entries(st.media_qc?.checks || {}).filter(([, v]) => !v.ok).map(([k, v]) => `${k}=${v.value} (expected ${v.expected})`);
  throw new Error(`${pkg.video_id} | media QC failed: ${bad.join('; ') || st.error || 'no QC result'}`);
}
const md = pkg.metadata_final;
const mmss = (t) => `${Math.floor(t / 60)}:${String(Math.floor(t % 60)).padStart(2, '0')}`;
const chapters = (st.timeline?.chapters || []).map((c) => `${mmss(c.t)} ${c.label}`).join('\n');
const seenChorus = new Set();
const lyrics = pkg.song.sections.map((s) => {
  if (s.type === 'chorus') {
    const key = s.lines.join('|');
    if (seenChorus.has(key)) return '(Chorus)';
    seenChorus.add(key);
  }
  return s.lines.join('\n');
}).join('\n\n');
const disclosure = `${cfg.channel_name} makes original sing-along songs for little ones. The song, lyrics and artwork were created for this channel with the help of AI tools.`;
let description = [md.description, chapters && `Chapters:\n${chapters}`, `Lyrics:\n${lyrics}`, disclosure, md.hashtags.map((h) => `#${h}`).join(' ')]
  .filter(Boolean).join('\n\n');
if (description.length > 4500) description = description.slice(0, 4500);

// next publish slot: configured weekday + UTC time, at least 2 hours ahead
const [hh, mi] = String(cfg.publish_time_utc || '12:00').split(':').map(Number);
const slot = new Date();
slot.setUTCHours(hh, mi, 0, 0);
while (slot.getTime() < Date.now() + 2 * 3600 * 1000 || !(cfg.publish_days_utc || [1, 3, 5]).includes(slot.getUTCDay())) {
  slot.setUTCDate(slot.getUTCDate() + 1);
}
const mode = ['manual_outbox', 'api_private', 'api_scheduled'].includes(cfg.upload_mode) ? cfg.upload_mode : 'manual_outbox';
const upload = {
  mode, title: md.title, description, tags: md.tags.join(','),
  category_id: String(cfg.category_id || '27'), region_code: cfg.region_code || 'IN', language: cfg.language || 'en',
  publish_at: slot.toISOString(),
  playlist_id: (cfg.playlist_ids || {})[(cfg.category_playlist || {})[pkg.idea.category]] || cfg.playlist_id || '',
  playlist_name: (cfg.category_playlist || {})[pkg.idea.category] || '',
};
return [{
  json: {
    pkg, upload,
    render: {
      duration_s: st.timeline?.duration_s, video_path: st.paths?.video, thumbnail_path: st.paths?.thumbnail,
      song_mode: st.song?.mode, intelligibility: st.song?.intelligibility,
    },
    route_index: { manual_outbox: 0, api_private: 1, api_scheduled: 2 }[mode],
  },
}];

// UPLOAD RESULT — normalises the YouTube response from either upload node.
const yt = $input.first().json;
const prev = $('Media QC Gate').first().json;
if (!yt.id) throw new Error(`${prev.pkg.video_id} | YouTube upload returned no video id: ${JSON.stringify(yt).slice(0, 300)}`);
return [{
  json: {
    ...prev,
    youtube: {
      id: yt.id,
      url: `https://www.youtube.com/watch?v=${yt.id}`,
      privacy: yt.status?.privacyStatus || '',
      publish_at: yt.status?.publishAt || '',
      made_for_kids: yt.status?.selfDeclaredMadeForKids ?? true,
      uploaded_at: new Date().toISOString(),
    },
  },
}];
